package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="movimentacao_financeira",schema="adm_eclesial") public class MovimentacaoFinanceira { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="conta_financeira_id",nullable=false) Long contaFinanceiraId; @Column(name="categoria_financeira_id") Long categoriaFinanceiraId; @Column(name="centro_custo_id") Long centroCustoId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) TipoMovimentacaoFinanceira tipo; @Column(nullable=false,precision=15,scale=2) BigDecimal valor; @Column(name="data_movimentacao",nullable=false) LocalDate dataMovimentacao; @Column LocalDate competencia; @Column(length=500) String descricao; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) StatusMovimentacaoFinanceira status; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public Long getContaFinanceiraId(){return contaFinanceiraId;} public Long getCategoriaFinanceiraId(){return categoriaFinanceiraId;} public Long getCentroCustoId(){return centroCustoId;} public TipoMovimentacaoFinanceira getTipo(){return tipo;} public BigDecimal getValor(){return valor;} public LocalDate getDataMovimentacao(){return dataMovimentacao;} public LocalDate getCompetencia(){return competencia;} public String getDescricao(){return descricao;} public StatusMovimentacaoFinanceira getStatus(){return status;} public void setContaFinanceiraId(Long v){contaFinanceiraId=v;} public void setCategoriaFinanceiraId(Long v){categoriaFinanceiraId=v;} public void setCentroCustoId(Long v){centroCustoId=v;} public void setTipo(TipoMovimentacaoFinanceira v){tipo=v;} public void setValor(BigDecimal v){valor=v;} public void setDataMovimentacao(LocalDate v){dataMovimentacao=v;} public void setCompetencia(LocalDate v){competencia=v;} public void setDescricao(String v){descricao=v;} public void setStatus(StatusMovimentacaoFinanceira v){status=v;} }